import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
@SpringBootTest(properties={"spring.datasource.username=root","spring.datasource.password=","spring.flyway.enabled=true","market.product-cache.enabled=false","market.login-protection.enabled=false","market.orders.mq.enabled=false","market.notifications.mq.enabled=false","market.orders.timeout-sweep-enabled=false","springdoc.api-docs.enabled=false"})
@AutoConfigureMockMvc
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="LESSON85_DB_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/campus_lesson85_verify\\?.*")
class AdminOrderIssueIntegrationTest {
    static Connection control;static String schema;
    @DynamicPropertySource static void database(DynamicPropertyRegistry registry)throws Exception {
        String base=System.getenv("LESSON85_DB_URL");control=DriverManager.getConnection(base,"root","");
        try(var s=control.createStatement();var r=s.executeQuery("SELECT @@datadir")){assertTrue(r.next());assertTrue(r.getString(1).contains("campus-lesson24-"));}
        schema="campus_lesson105_case_"+UUID.randomUUID().toString().replace("-","").substring(0,12);
        try(var s=control.createStatement()){s.execute("CREATE DATABASE "+schema+" CHARACTER SET utf8mb4");}
        registry.add("spring.datasource.url",()->base.replace("/campus_lesson85_verify?","/"+schema+"?"));
    }
    @AfterAll static void removeSchema()throws Exception {if(control!=null)try{if(schema!=null&&schema.matches("campus_lesson105_case_[0-9a-f]{12}"))try(var s=control.createStatement()){s.execute("DROP DATABASE "+schema);}}finally{control.close();}}
    @Autowired AdminOrderIssueService adminIssues;@Autowired NotificationOutbox outbox;@Autowired SessionService sessions;@Autowired OrderIssueService issues;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;
    @Autowired org.springframework.transaction.PlatformTransactionManager transactions;@Autowired javax.sql.DataSource source;
    final JsonMapper json=JsonMapper.builder().build();String buyer,seller,outsider,admin,secondAdmin;
    @BeforeEach void fixtures(){
        for(String table:List.of("order_issue_resolutions","order_issues","order_reviews","user_notifications","notification_outbox","order_events","order_timeout_outbox","market_orders","products","user_role_audit","user_role_grants","login_sessions","users"))jdbc.update("DELETE FROM "+table);
        jdbc.update("INSERT INTO users(id,username,password_hash,nickname) VALUES(101,'review_buyer','PRIVATE_HASH','甲'),(102,'review_seller','PRIVATE_HASH','乙'),(103,'review_outsider','PRIVATE_HASH','丙')");
        String[] states={"COMPLETED","PAID","PENDING_PAYMENT","DELIVERED","CANCELLED","CLOSED_TIMEOUT"};
        for(int i=0;i<states.length;i++){
            long id=i+1;String state=states[i];boolean paid=Set.of("PAID","DELIVERED","COMPLETED").contains(state),delivered=Set.of("DELIVERED","COMPLETED").contains(state);
            jdbc.update("INSERT INTO products(id,title,description,price_in_cents,seller_id,status) VALUES(?,'隔离评价样本','只用于本课测试',100,102,?)",id,paid?"SOLD":"ON_SALE");
            String created="CURRENT_TIMESTAMP(6)-INTERVAL 20 MINUTE";
            String query="INSERT INTO market_orders(id,product_id,buyer_id,seller_id,request_id,product_title_snapshot,price_in_cents_snapshot,product_version_snapshot,buyer_nickname_snapshot,seller_nickname_snapshot,status,created_at,cancelled_at,paid_at,closed_at,payment_kind,delivered_at,completed_at) VALUES(?,?,101,102,?,'隔离评价样本',100,0,'甲','乙',?,"+created+","+(state.equals("CANCELLED")?"CURRENT_TIMESTAMP(6)-INTERVAL 19 MINUTE":"NULL")+","+(paid?"CURRENT_TIMESTAMP(6)-INTERVAL 19 MINUTE":"NULL")+","+(state.equals("CLOSED_TIMEOUT")?"CURRENT_TIMESTAMP(6)-INTERVAL 4 MINUTE":"NULL")+","+(paid?"'SIMULATED'":"NULL")+","+(delivered?"CURRENT_TIMESTAMP(6)-INTERVAL 18 MINUTE":"NULL")+","+(state.equals("COMPLETED")?"CURRENT_TIMESTAMP(6)-INTERVAL 17 MINUTE":"NULL")+")";
            jdbc.update(query,id,id,UUID.randomUUID().toString(),state);
        }
        buyer=issue(101);seller=issue(102);outsider=issue(103);
        jdbc.update("INSERT INTO users(id,username,password_hash,nickname) VALUES(201,'issue_admin','PRIVATE_HASH','管理员甲'),(202,'issue_admin2','PRIVATE_HASH','管理员乙')");
        jdbc.update("INSERT INTO user_role_grants(user_id,role_code) VALUES(201,'ADMIN'),(202,'ADMIN')");admin=issue(201);secondAdmin=issue(202);
        issues.create("1",new OrderIssueModels.Create("ITEM_CONDITION","交接时发现商品存在故障，请协助核对处理。"),buyer);
    }
    String issue(long id){return "Bearer "+sessions.issueToken(new UserResponse(id,"review_"+id,"隔离验收")).accessToken();}
    final String description="交接时发现商品存在故障，请协助核对处理。";
    MockHttpServletResponse read(String id,String token)throws Exception {var r=get("/api/orders/"+id+"/issue");if(token!=null)r.header("Authorization",token);return mvc.perform(r).andReturn().getResponse();}
    MockHttpServletResponse postIssue(String id,String token,String body)throws Exception {var r=post("/api/orders/"+id+"/issue").contentType("application/json").content(body);if(token!=null)r.header("Authorization",token);return mvc.perform(r).andReturn().getResponse();}
    MockHttpServletResponse submit(String id,String token,String reason,String text)throws Exception{return postIssue(id,token,json.writeValueAsString(Map.of("reason",reason,"description",text)));}
    MockHttpServletResponse submit(String token)throws Exception{return submit("1",token,"ITEM_CONDITION",description);}
    JsonNode node(MockHttpServletResponse r,int expected)throws Exception {assertEquals(expected,r.getStatus(),r.getContentAsString());assertEquals("no-store",r.getHeader("Cache-Control"));return json.readTree(r.getContentAsByteArray());}
    long count(){return jdbc.queryForObject("SELECT COUNT(*) FROM order_issues",Long.class);}
    final String explanation="已记录你的反馈，请双方核对商品及交接情况。";
    String key(){return UUID.randomUUID().toString();}
    long resolved(){return jdbc.queryForObject("SELECT COUNT(*) FROM order_issue_resolutions",Long.class);}
    long jobs(){return jdbc.queryForObject("SELECT COUNT(*) FROM notification_outbox",Long.class);}
    MockHttpServletResponse list(String token,String status,int page,int size)throws Exception {var r=get("/api/admin/order-issues").param("status",status).param("page",""+page).param("size",""+size);if(token!=null)r.header("Authorization",token);return mvc.perform(r).andReturn().getResponse();}
    MockHttpServletResponse detail(String order,String applicant,String token)throws Exception {var r=get("/api/admin/order-issues/"+order+"/"+applicant);if(token!=null)r.header("Authorization",token);return mvc.perform(r).andReturn().getResponse();}
    MockHttpServletResponse resolve(String order,String applicant,String token,String decision,String text,String key)throws Exception {var r=post("/api/admin/order-issues/"+order+"/"+applicant+"/resolve").contentType("application/json").content(json.writeValueAsString(Map.of("decision",decision,"explanation",text,"requestId",key)));if(token!=null)r.header("Authorization",token);return mvc.perform(r).andReturn().getResponse();}
    MockHttpServletResponse resolve(String token,String key)throws Exception{return resolve("1","101",token,"ANSWERED",explanation,key);}
    @Test void anonymousCannotListReadOrResolve()throws Exception {assertEquals(401,list(null,"OPEN",1,10).getStatus());assertEquals(401,detail("1","101",null).getStatus());assertEquals(401,resolve(null,key()).getStatus());}
    @Test void ordinaryParticipantsCannotAccessAdminRoutes()throws Exception {for(String token:List.of(buyer,seller,outsider)){assertEquals(403,list(token,"OPEN",1,10).getStatus());assertEquals(403,detail("1","101",token).getStatus());assertEquals(403,resolve(token,key()).getStatus());}assertEquals(0,resolved());}
    @Test void liveGrantRevocationBlocksFurtherRequests()throws Exception {node(list(admin,"OPEN",1,10),200);jdbc.update("DELETE FROM user_role_grants WHERE user_id=201");assertEquals(403,detail("1","101",admin).getStatus());assertEquals(403,resolve(admin,key()).getStatus());}
    @Test void revokedSessionIs401()throws Exception {sessions.logout(admin);assertEquals(401,resolve(admin,key()).getStatus());assertEquals(401,list(admin,"OPEN",1,10).getStatus());}
    @Test void canonicalIdsAreRequired()throws Exception {for(String id:List.of("0","01","-1","1e1","9007199254740992")){assertEquals(400,detail(id,"101",admin).getStatus());assertEquals(400,detail("1",id,admin).getStatus());}}
    @Test void missingCompositeCaseIs404()throws Exception {assertEquals(404,detail("1","103",admin).getStatus());assertEquals(404,resolve("1","103",admin,"ANSWERED",explanation,key()).getStatus());}
    @Test void filtersPagingAndWhitespaceAreStrict()throws Exception {for(String status:List.of("","open","RESOLVED ","OPEN' OR 1=1"))assertEquals(400,list(admin,status,1,10).getStatus());for(int page:new int[]{0,-1,1000001})assertEquals(400,list(admin,"OPEN",page,10).getStatus());for(int size:new int[]{0,-1,21})assertEquals(400,list(admin,"OPEN",1,size).getStatus());}
    @Test void emptyFilterClampsToFirstPage()throws Exception {var n=node(list(admin,"RESOLVED",99,10),200);assertEquals(0,n.path("total").asLong());assertEquals(1,n.path("page").asInt());assertEquals(0,n.path("items").size());}
    @Test void listContainsMinimalRowsWithoutDescription()throws Exception {var n=node(list(admin,"OPEN",1,10),200);assertEquals(Set.of("status","age","orderId","sampledAt","page","size","total","totalPages","items"),new HashSet<>(n.propertyNames()));var row=n.path("items").get(0);assertEquals(Set.of("orderId","applicantId","applicantRole","reason","createdAt","status"),new HashSet<>(row.propertyNames()));assertEquals("BUYER",row.path("applicantRole").asString());assertFalse(n.toString().contains(description));}
    @Test void buyerAndSellerCasesAreIndependent()throws Exception {issues.create("1",new OrderIssueModels.Create("OTHER","卖家另行提交的说明，只属于卖家的反馈记录。"),seller);assertEquals(2,node(list(admin,"OPEN",1,10),200).path("total").asLong());assertEquals(description,node(detail("1","101",admin),200).path("description").asString());assertFalse(node(detail("1","102",admin),200).path("description").asString().contains(description));}
    @Test void detailUsesOrderSnapshotNotCurrentProduct()throws Exception {jdbc.update("UPDATE products SET title='现时商品标题',price_in_cents=9999 WHERE id=1");var n=node(detail("1","101",admin),200);assertEquals("隔离评价样本",n.path("productTitleSnapshot").asString());assertEquals(100,n.path("priceInCentsSnapshot").asLong());}
    @Test void firstResolutionStoresAuditAndOneNotification()throws Exception {String key=key();var n=node(resolve(admin,key),200);assertFalse(n.path("replayed").asBoolean());assertEquals("RESOLVED",n.at("/detail/status").asString());assertEquals(201,jdbc.queryForObject("SELECT resolver_id FROM order_issue_resolutions",Long.class));assertEquals(key,jdbc.queryForObject("SELECT request_id FROM order_issue_resolutions",String.class));assertEquals(1,resolved());assertEquals(1,jobs());}
    @Test void sameKeyPayloadReplaysAndPreservesFirstTime()throws Exception {String key=key();node(resolve(admin,key),200);var before=jdbc.queryForList("SELECT * FROM order_issue_resolutions");var job=jdbc.queryForList("SELECT * FROM notification_outbox");var n=node(resolve("1","101",admin,"ANSWERED"," \r\n"+explanation+"\u00a0",key),200);assertTrue(n.path("replayed").asBoolean());assertEquals(before,jdbc.queryForList("SELECT * FROM order_issue_resolutions"));assertEquals(job,jdbc.queryForList("SELECT * FROM notification_outbox"));}
    @Test void differentKeyOrContentCannotOverwrite()throws Exception {String key=key();resolve(admin,key);var before=jdbc.queryForList("SELECT * FROM order_issue_resolutions");assertEquals(409,resolve(admin,key()).getStatus());assertEquals(409,resolve("1","101",admin,"DISMISSED",explanation,key).getStatus());assertEquals(409,resolve("1","101",admin,"ANSWERED",explanation+"补充",key).getStatus());assertEquals(before,jdbc.queryForList("SELECT * FROM order_issue_resolutions"));assertEquals(1,jobs());}
    @Test void anotherAdministratorCannotReplayOrReplace()throws Exception {String key=key();resolve(admin,key);assertEquals(409,resolve(secondAdmin,key).getStatus());assertEquals(1,resolved());assertEquals(1,jobs());}
    @Test void sameAdminKeyCannotBeReusedForAnotherCase()throws Exception {issues.create("1",new OrderIssueModels.Create("OTHER",description),seller);String key=key();resolve(admin,key);assertEquals(409,resolve("1","102",admin,"ANSWERED",explanation,key).getStatus());assertEquals(1,resolved());assertEquals(1,jobs());}
    @Test void participantAdministratorsCannotHandleOwnTrade()throws Exception {for(long user:List.of(101L,102L)){jdbc.update("INSERT INTO user_role_grants(user_id,role_code) VALUES(?,'ADMIN')",user);assertEquals(403,resolve(user==101?buyer:seller,key()).getStatus());}assertEquals(0,resolved());}
    @Test void decisionExplanationAndRequestKeyAreValidated()throws Exception {for(String decision:List.of("REFUND","answered","ANSWERED "))assertEquals(400,resolve("1","101",admin,decision,explanation,key()).getStatus());for(String text:List.of("short","字".repeat(1001),explanation+"\u0000"))assertEquals(400,resolve("1","101",admin,"ANSWERED",text,key()).getStatus());for(String key:List.of("x","AAAAAAAA-AAAA-AAAA-AAAA-AAAAAAAAAAAA","1-1-1-1-1"))assertEquals(400,resolve(admin,key).getStatus());assertEquals(0,resolved());}
    @Test void resolutionRejectsJsonCoercion()throws Exception {for(String value:List.of("1234567890","true","{}","null")){String body="{\"decision\":\"ANSWERED\",\"explanation\":"+value+",\"requestId\":\""+key()+"\"}";assertEquals(400,mvc.perform(post("/api/admin/order-issues/1/101/resolve").header("Authorization",admin).contentType("application/json").content(body)).andReturn().getResponse().getStatus());}}
    @Test void unicodeLimitAndDismissalAreSupported()throws Exception {node(resolve("1","101",admin,"DISMISSED","😀".repeat(1000),key()),200);assertEquals("DISMISSED",issues.summary("1",buyer).issue().resolution().decision());}
    @Test void applicantSeesResultButNotAdministratorOrRequestKey()throws Exception {String key=key();resolve(admin,key);var n=node(read("1",buyer),200);assertEquals(explanation,n.at("/issue/resolution/explanation").asString());assertEquals(Set.of("decision","explanation","createdAt"),new HashSet<>(n.at("/issue/resolution").propertyNames()));assertFalse(n.toString().contains(key));for(String privateField:List.of("resolverId","issue_admin","requestId","PRIVATE_HASH"))assertFalse(n.toString().contains(privateField));assertTrue(node(read("1",seller),200).path("issue").isNull());}
    @Test void notificationIsGenericAndOnlyForApplicant()throws Exception {resolve(admin,key());var n=jdbc.queryForMap("SELECT recipient_id,category,resource_id,title,body FROM notification_outbox");assertEquals(101L,((Number)n.get("recipient_id")).longValue());assertEquals("ORDER",n.get("category"));assertEquals(1L,((Number)n.get("resource_id")).longValue());String text=n.get("title")+" "+n.get("body");assertFalse(text.contains(description));assertFalse(text.contains(explanation));assertFalse(text.contains("ANSWERED"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM user_notifications",Long.class));}
    Map<String,List<Map<String,Object>>> stable(){var map=new TreeMap<String,List<Map<String,Object>>>();for(String table:List.of("order_issues","market_orders","products","order_reviews","order_events","order_timeout_outbox","user_notifications"))map.put(table,jdbc.queryForList("SELECT * FROM "+table));return map;}
    @Test void resolutionDoesNotChangeOriginalFeedbackOrTrade()throws Exception {var before=stable();resolve(admin,key());assertEquals(before,stable());}
    @Test void readsDoNotWriteTasksOrResolution()throws Exception {var before=stable();node(list(admin,"ALL",1,10),200);node(detail("1","101",admin),200);node(read("1",buyer),200);assertEquals(before,stable());assertEquals(0,resolved());assertEquals(0,jobs());}
    @Test void outboxFailureRollsBackResolution()throws Exception {jdbc.execute("CREATE TRIGGER private_resolution_outbox_failure BEFORE INSERT ON notification_outbox FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private failure'");try{assertEquals(500,resolve(admin,key()).getStatus());assertEquals(0,resolved());assertEquals(0,jobs());assertEquals(1,count());}finally{jdbc.execute("DROP TRIGGER private_resolution_outbox_failure");}}
    @Test void resolutionInsertFailureCreatesNoNotification()throws Exception {jdbc.execute("CREATE TRIGGER private_resolution_failure BEFORE INSERT ON order_issue_resolutions FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private failure'");try{assertEquals(500,resolve(admin,key()).getStatus());assertEquals(0,resolved());assertEquals(0,jobs());}finally{jdbc.execute("DROP TRIGGER private_resolution_failure");}}
    @Test void outerRollbackRemovesResolutionAndNotice(){new org.springframework.transaction.support.TransactionTemplate(transactions).executeWithoutResult(tx->{adminIssues.resolve("1","101",new AdminOrderIssueModels.Resolve("ANSWERED",explanation,key()),admin);tx.setRollbackOnly();});assertEquals(0,resolved());assertEquals(0,jobs());}
    @Test void corruptionIs503NotFalsePendingOrSuccess()throws Exception {resolve(admin,key());jdbc.update("UPDATE order_issue_resolutions SET created_at=CURRENT_TIMESTAMP-INTERVAL 30 MINUTE");assertEquals(503,detail("1","101",admin).getStatus());assertEquals(503,read("1",buyer).getStatus());}
    @Test void unavailableResolutionTableIs500()throws Exception {jdbc.execute("RENAME TABLE order_issue_resolutions TO order_issue_resolutions_private_unavailable");try{assertEquals(500,list(admin,"OPEN",1,10).getStatus());assertEquals(500,read("1",buyer).getStatus());}finally{jdbc.execute("RENAME TABLE order_issue_resolutions_private_unavailable TO order_issue_resolutions");}}
    @Test void resolutionMovesFilteredCountsAndClampsPage()throws Exception {issues.create("1",new OrderIssueModels.Create("OTHER",description),seller);assertEquals(2,node(list(admin,"OPEN",2,1),200).path("page").asInt());resolve(admin,key());var remaining=node(list(admin,"OPEN",2,1),200);assertEquals(1,remaining.path("page").asInt());assertEquals(102,remaining.at("/items/0/applicantId").asLong());assertEquals(1,node(list(admin,"RESOLVED",1,10),200).path("total").asLong());assertEquals(2,node(list(admin,"ALL",1,10),200).path("total").asLong());}
    @Test void concurrentAdminsResolveOnce()throws Exception {var responses=concurrent(admin,secondAdmin,key(),key());var codes=responses.stream().map(MockHttpServletResponse::getStatus).sorted().toList();assertEquals(List.of(200,409),codes);assertEquals(1,resolved());assertEquals(1,jobs());}
    @Test void concurrentSameKeyCreatesOnceAndReplaysOnce()throws Exception {String key=key();var responses=concurrent(admin,admin,key,key);assertEquals(List.of(200,200),responses.stream().map(MockHttpServletResponse::getStatus).toList());int replayed=0;for(var response:responses)if(json.readTree(response.getContentAsByteArray()).path("replayed").asBoolean())replayed++;assertEquals(1,replayed);assertEquals(1,resolved());assertEquals(1,jobs());}
    List<MockHttpServletResponse> concurrent(String a,String b,String x,String y)throws Exception {var pool=java.util.concurrent.Executors.newFixedThreadPool(2);var gate=new java.util.concurrent.CountDownLatch(1);try{var first=pool.submit(()->{gate.await();return resolve(a,x);});var second=pool.submit(()->{gate.await();return resolve(b,y);});gate.countDown();return List.of(first.get(5,java.util.concurrent.TimeUnit.SECONDS),second.get(5,java.util.concurrent.TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
    @Test void permissionRevokedWhileWaitingForIssueLockCannotWrite()throws Exception {waitAndRevoke(false,403);}
    @Test void sessionRevokedWhileWaitingForIssueLockCannotWrite()throws Exception {waitAndRevoke(true,401);}
    void waitAndRevoke(boolean session,int expected)throws Exception {var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try(var c=source.getConnection()){c.setAutoCommit(false);c.createStatement().executeQuery("SELECT order_id FROM order_issues WHERE order_id=1 AND applicant_id=101 FOR UPDATE").close();var f=pool.submit(()->resolve(admin,key()).getStatus());assertThrows(java.util.concurrent.TimeoutException.class,()->f.get(200,java.util.concurrent.TimeUnit.MILLISECONDS));if(session)sessions.logout(admin);else jdbc.update("DELETE FROM user_role_grants WHERE user_id=201");c.commit();assertEquals(expected,f.get(5,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,resolved());assertEquals(0,jobs());}finally{pool.shutdownNow();}}
    @Test void originalSubmissionReplayDoesNotEraseResolution()throws Exception {resolve(admin,key());var n=node(submit(buyer),200);assertTrue(n.path("replayed").asBoolean());assertEquals(explanation,n.at("/summary/issue/resolution/explanation").asString());assertEquals(1,resolved());assertEquals(1,jobs());}
    @Test void listAndDetailShareRepeatableReadSnapshot()throws Exception {var tx=new org.springframework.transaction.support.TransactionTemplate(transactions);tx.setReadOnly(true);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);tx.executeWithoutResult(status->{assertEquals(1,adminIssues.page("OPEN",1,10,admin).total());var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{pool.submit(()->adminIssues.resolve("1","101",new AdminOrderIssueModels.Resolve("ANSWERED",explanation,key()),secondAdmin)).get(5,java.util.concurrent.TimeUnit.SECONDS);assertEquals(1,adminIssues.page("OPEN",1,10,admin).total());assertEquals("OPEN",adminIssues.detail("1","101",admin).status());}catch(Exception e){throw new RuntimeException(e);}finally{pool.shutdownNow();}});assertEquals(0,adminIssues.page("OPEN",1,10,admin).total());}
}
